  listExecutions(workflowId: string, limit?: number): Promise<WorkflowExecution[]>;
  findExecutionByIdempotencyKey(
    workflowId: string,
    idempotencyKey: string
  ): Promise<WorkflowExecution | null>;
}

/**
 * Workflow storage implementation using adapter
 */
export class AdapterWorkflowStorage implements WorkflowStorage {
  private readonly adapter: PlugFnDatabaseStorageAdapter;

  constructor(adapter: DbAdapter | PlugFnDatabaseStorageAdapter) {
    this.adapter = ensurePlugFnDatabaseAdapter(adapter);
  }

  async create(workflow: Omit<Workflow, 'id' | 'createdAt' | 'updatedAt'>): Promise<Workflow> {
    const id = this.generateId();
    const now = new Date();

    const fullWorkflow: Workflow = {
      ...workflow,
      id,
      createdAt: now,
      updatedAt: now,
    };

    return this.adapter.createWorkflow(fullWorkflow);
  }

  async get(id: string): Promise<Workflow | null> {
    return this.adapter.getWorkflow(id);
  }

  async list(userId?: string, status?: WorkflowStatus): Promise<Workflow[]> {
    return this.adapter.listWorkflows(userId, status);
  }

  async update(id: string, updates: Partial<Workflow>): Promise<Workflow> {
    await this.adapter.updateWorkflow(id, {
      ...updates,
      updatedAt: new Date(),
    });

    const updated = await this.adapter.getWorkflow(id);
    if (!updated) {
      throw new Error(`Workflow ${id} not found after update`);
    }

    return updated;
  }

  async delete(id: string): Promise<void> {
    await this.adapter.deleteWorkflow(id);
  }

  async createExecution(execution: Omit<WorkflowExecution, 'id' | 'startedAt'>): Promise<WorkflowExecution> {
    const id = this.generateExecutionId();
    const startedAt = new Date();

    const fullExecution: WorkflowExecution = {
      ...execution,
      id,
      startedAt,
    };

    return this.adapter.createWorkflowExecution(fullExecution);
  }

  async getExecution(id: string): Promise<WorkflowExecution | null> {
    const executions = await this.adapter.database.findMany<WorkflowExecution>({
      model: this.adapter.models.workflowExecutions,
      where: [{ field: 'id', operator: 'eq', value: id }],
      limit: 1,
    });

    return executions[0] ?? null;
  }

  async updateExecution(id: string, updates: Partial<WorkflowExecution>): Promise<void> {
    await this.adapter.updateWorkflowExecution(id, updates);
  }

  async listExecutions(workflowId: string, limit?: number): Promise<WorkflowExecution[]> {
    return this.adapter.listWorkflowExecutions(workflowId, limit);
  }

  async findExecutionByIdempotencyKey(
    workflowId: string,
    idempotencyKey: string
  ): Promise<WorkflowExecution | null> {
    const executions = await this.adapter.listWorkflowExecutions(workflowId, 1000);

    for (const execution of executions) {
      const input = execution.input as Record<string, unknown> | undefined;
      const workflowInput = input?.__workflow as Record<string, unknown> | undefined;
      const inputKey =
        typeof workflowInput?.idempotencyKey === 'string'
          ? workflowInput.idempotencyKey
          : typeof input?.idempotencyKey === 'string'
            ? input.idempotencyKey
            : undefined;
      if (inputKey === idempotencyKey) {
        return execution;
      }

      const output = execution.output as Record<string, unknown> | undefined;
      const workflowOutput = output?.__workflow as Record<string, unknown> | undefined;
      const outputKey =
        typeof workflowOutput?.idempotencyKey === 'string'
          ? workflowOutput.idempotencyKey
          : undefined;
      if (outputKey === idempotencyKey) {
        return execution;
      }
    }

    return null;
  }

  private generateId(): string {
    return `wf_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private generateExecutionId(): string {
    return `wfx_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

import type {
  FileFn,
  FileArtifactRecord,
  Policy,
} from "@filefn/server";
import {
  AdminError,
  decodeAdminCursor,
  encodeAdminCursor,
  normalizeAdminPageLimit,
  type AdminOperationContext,
  type AdminOperationResult,
} from "@superfunctions/admin";
import type {
  FileFnAdminService,
  FileFnAdminServiceRequest,
  PageInput,
} from "./index.js";

type JsonRecord = Record<string, unknown>;

export interface FileFnDomainContext {
  principalId?: string;
  tenantId?: string;
  requestId?: string;
}

export interface FileFnDomainAdminServiceOptions {
  /** Public FileFn facade and its bound service bundle. */
  fileFn: FileFn;
  /** Maps the active admin actor/scope to FileFn's principal and tenant identity. */
  context(admin: AdminOperationContext): FileFnDomainContext;
}

function domainContext(options: FileFnDomainAdminServiceOptions, admin: AdminOperationContext): FileFnDomainContext & { principalId: string } {
  const mapped = options.context(admin);
  const principalId = mapped.principalId;
  if (!principalId) {
    throw new AdminError("invalid_argument", "FileFn administration requires a mapped principalId.");
  }
  return { ...mapped, principalId, requestId: mapped.requestId ?? admin.requestId };
}

function record(value: unknown, label: string): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new AdminError("internal", `${label} returned an invalid domain object.`);
  }
  return value as JsonRecord;
}

function item(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { item: { ...value } } };
}

function accepted(value?: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { accepted: true, ...(value ? { item: { ...value } } : {}) } };
}

function page<T extends object>(values: readonly T[], input: PageInput, admin: AdminOperationContext): AdminOperationResult<JsonRecord> {
  const limit = normalizeAdminPageLimit(input.limit, { defaultLimit: 50, maxLimit: 100 });
  const offset = input.cursor ? decodeAdminCursor<{ offset: number }>(input.cursor, admin.scope).offset : 0;
  if (!Number.isInteger(offset) || offset < 0) {
    throw new AdminError("invalid_argument", "The FileFn admin cursor is invalid.");
  }
  const items = values.slice(offset, offset + limit).map((value) => ({ ...value }));
  const nextOffset = offset + items.length;
  const nextCursor = nextOffset < values.length ? encodeAdminCursor(admin.scope, { offset: nextOffset }) : null;
  return { ok: true, data: { items, nextCursor }, page: { nextCursor, hasMore: nextOffset < values.length } };
}

function safeVersion(value: JsonRecord): JsonRecord {
  const { storageKey: _storageKey, ...safe } = value;
  return safe;
}

function safeArtifact(value: FileArtifactRecord): JsonRecord {
  const { storageKey: _storageKey, ...safe } = value;
  return safe;
}

function safePolicy(value: Policy): JsonRecord {
  const { storagePath, ...safe } = value;
  return { ...safe, customStoragePath: Boolean(storagePath) };
}

function findById<T extends object>(values: readonly T[], predicate: (value: T) => boolean, label: string): T {
  const value = values.find(predicate);
  if (!value) throw new AdminError("not_found", `${label} was not found in the active FileFn project.`);
  return value;
}

/**
 * Binds the administration capability to FileFn's public domain services. The
 * adapter never reads FileFn tables directly, so owner/tenant authorization,
 * policy validation, quotas, storage routing, lifecycle cleanup, and events
 * remain enforced by FileFn itself.
 */
export function createFileFnDomainAdminService(options: FileFnDomainAdminServiceOptions): FileFnAdminService {
  const { files, grants, shares, processing, policies } = options.fileFn.services;
  return {
    async execute(request: FileFnAdminServiceRequest): Promise<AdminOperationResult<JsonRecord>> {
      const ctx = domainContext(options, request.context);

      switch (request.operationId) {
        case "filefn.files.list": {
          const result = record(await options.fileFn.listFiles(request.input, ctx), "FileFn.listFiles");
          const files = Array.isArray(result.files) ? result.files : [];
          const nextCursor = typeof result.nextCursor === "string" ? result.nextCursor : null;
          return { ok: true, data: { items: files, nextCursor }, page: { nextCursor, hasMore: nextCursor !== null } };
        }
        case "filefn.files.get":
          return item(record(await options.fileFn.getFile({ fileId: request.input.id }, ctx), "FileFn.getFile"));
        case "filefn.files.download":
          return item(await files.getDownloadUrl(request.input.id, request.input.versionId, ctx));
        case "filefn.files.delete-file":
          await options.fileFn.deleteFile({ fileId: request.input.id }, ctx);
          return accepted();
        case "filefn.versions.list": {
          const result = await files.listVersions(request.input.fileId, ctx);
          return page(result.versions.map((version) => safeVersion({ ...version })), request.input, request.context);
        }
        case "filefn.versions.get":
          return item(safeVersion({ ...await files.getVersion(request.input.fileId, request.input.id, ctx) }));
        case "filefn.upload-sessions.get": {
          const uploadCtx = { ...ctx, ...(request.input.uploadSessionToken ? { uploadSessionToken: request.input.uploadSessionToken } : {}) };
          return item(record(await options.fileFn.getUploadSessionStatus({ uploadSessionId: request.input.id }, uploadCtx), "FileFn.getUploadSessionStatus"));
        }
        case "filefn.upload-sessions.create-upload": {
          const result = await options.fileFn.createUploadSession({ ...request.input, idempotencyKey: request.context.idempotencyKey }, ctx);
          return accepted(result);
        }
        case "filefn.upload-sessions.complete-upload": {
          const uploadCtx = { ...ctx, ...(request.input.uploadSessionToken ? { uploadSessionToken: request.input.uploadSessionToken } : {}) };
          return accepted(await options.fileFn.completeUploadSession({ uploadSessionId: request.input.id }, uploadCtx));
        }
        case "filefn.upload-sessions.abort-upload": {
          const uploadCtx = { ...ctx, ...(request.input.uploadSessionToken ? { uploadSessionToken: request.input.uploadSessionToken } : {}) };
          await options.fileFn.abortUploadSession({ uploadSessionId: request.input.id }, uploadCtx);
          return accepted();
        }
        case "filefn.grants.list":
          return page(await grants.listGrants(request.input.fileId, ctx), request.input, request.context);
        case "filefn.grants.create-grant":
          return accepted(await grants.createGrant(request.input, ctx));
        case "filefn.grants.revoke-grant":
          await grants.revokeGrant(request.input.fileId, request.input.id, ctx);
          return accepted();
        case "filefn.share-links.list":
          return page(await shares.listShareLinks(request.input.fileId, ctx), request.input, request.context);
        case "filefn.share-links.create-share":
          return accepted(await shares.createShareLink(request.input, ctx));
        case "filefn.share-links.revoke-share":
          await shares.revokeShareLink(request.input.fileId, request.input.token, ctx);
          return accepted();
        case "filefn.policies.list":
          return page(policies.list().map(safePolicy), request.input, request.context);
        case "filefn.policies.get": {
          const policy = policies.get(request.input.id);
          if (!policy) throw new AdminError("not_found", "Policy was not found in the active FileFn project.");
          return item(safePolicy(policy));
        }
        case "filefn.artifacts.list":
          return page((await processing.listArtifactsForFile(request.input.fileId, ctx)).map(safeArtifact), request.input, request.context);
        case "filefn.artifacts.get": {
          const artifacts = await processing.listArtifactsForFile(request.input.fileId, ctx);
          return item(safeArtifact(findById(artifacts, (value) => value.artifactId === request.input.id, "Artifact")));
        }
        case "filefn.artifacts.download":
          return item(await processing.getArtifactDownloadUrlForFile(request.input.fileId, request.input.id, ctx));
        case "filefn.artifacts.process-file": {
          const readable = await processing.getReadableVersionForFile(request.input.fileId, ctx, request.input.versionId);
          return accepted(await processing.triggerProcessing({
            fileId: readable.file.fileId,
            versionId: readable.version.versionId,
            storageKey: readable.version.storageKey,
            mimeType: readable.version.mimeType,
            size: readable.version.size,
            fileName: readable.file.name,
            tenantId: readable.file.tenantId ?? undefined,
          }, ctx));
        }
      }
    },
  };
}
import type { SearchAdapter, SearchDocument } from "@searchfn/adapter-contracts";
import {
  AdminError,
  type AdminOperationContext,
  type AdminOperationResult,
} from "@superfunctions/admin";
import type { SearchFnAdminService, SearchFnAdminServiceRequest } from "./index.js";

type JsonRecord = Record<string, unknown>;

export interface SearchFnDomainAdminServiceOptions {
  /** Must resolve an adapter already isolated to the active scope and optional namespace/region. */
  adapter(context: AdminOperationContext): SearchAdapter | Promise<SearchAdapter>;
  /** Returns the configured index names visible inside the same isolated adapter. */
  resources(context: AdminOperationContext): readonly string[] | Promise<readonly string[]>;
}

function object(value: unknown, name: string): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new AdminError("invalid_argument", `${name} must be an object.`);
  }
  return value as JsonRecord;
}

function string(value: unknown, name: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new AdminError("invalid_argument", `${name} must be a non-empty string.`);
  }
  return value;
}

function item(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { item: { ...value } } };
}

function list(values: object[]): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { items: values.map((value) => ({ ...value })), nextCursor: null } };
}

function accepted(value: JsonRecord): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { accepted: true, ...value } };
}

function splitDocumentId(value: string): { resource: string; id: string | number } {
  const separator = value.indexOf(":");
  if (separator <= 0 || separator === value.length - 1) {
    throw new AdminError("invalid_argument", "SearchFn document targets use the form resource:id.");
  }
  const id = value.slice(separator + 1);
  return { resource: value.slice(0, separator), id: /^\d+$/.test(id) ? Number(id) : id };
}

function documents(value: unknown): SearchDocument[] {
  if (!Array.isArray(value) || value.length === 0) {
    throw new AdminError("invalid_argument", "payload.documents must be a non-empty array.");
  }
  return value.map((entry, index) => {
    const document = object(entry, `payload.documents[${index}]`);
    const id = document.id;
    if (typeof id !== "string" && typeof id !== "number") {
      throw new AdminError("invalid_argument", `payload.documents[${index}].id must be a string or number.`);
    }
    const fields = object(document.fields, `payload.documents[${index}].fields`);
    if (Object.values(fields).some((field) => typeof field !== "string")) {
      throw new AdminError("invalid_argument", `payload.documents[${index}].fields values must be strings.`);
    }
    return { id, fields: fields as Record<string, string> };
  });
}

/** Delegates to the configured SearchAdapter; no raw backend or cross-scope query is constructed here. */
export function createSearchFnDomainAdminService(
  options: SearchFnDomainAdminServiceOptions,
): SearchFnAdminService {
  return {
    async execute(request: SearchFnAdminServiceRequest) {
      const input = object(request.input ?? {}, "input");
      const adapter = await options.adapter(request.context);
      const resources = [...await options.resources(request.context)];
      const adapterInfo = {
        id: adapter.name,
        name: adapter.name,
        status: "available",
        capabilities: adapter.capabilities ?? {},
      };
      const indexInfo = resources.map((resource) => ({ id: resource, name: resource, status: "available" }));

      switch (request.operationId) {
        case "searchfn.adapters-backends.list":
          return list([adapterInfo]);
        case "searchfn.adapters-backends.get":
          return string(input.id, "id") === adapter.name
            ? item(adapterInfo)
            : Promise.reject(new AdminError("not_found", "SearchFn adapter was not found in the active scope."));
        case "searchfn.indexes-collections.list":
          return list(indexInfo);
        case "searchfn.indexes-collections.get": {
          const found = indexInfo.find((entry) => entry.id === string(input.id, "id"));
          if (!found) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          return item(found);
        }
        case "searchfn.health.list":
          return list([{ id: adapter.name, adapter: adapter.name, state: "ok", capabilities: adapter.capabilities ?? {} }]);
        case "searchfn.health.get":
          return string(input.id, "id") === adapter.name
            ? item({ id: adapter.name, adapter: adapter.name, state: "ok", capabilities: adapter.capabilities ?? {} })
            : Promise.reject(new AdminError("not_found", "SearchFn health target was not found."));
        case "searchfn.documents.index":
        {
          const target = splitDocumentId(string(input.id, "id"));
          if (!resources.includes(target.resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          const payload = object(input.payload, "payload");
          const fields = object(payload.fields, "payload.fields");
          if (Object.values(fields).some((field) => typeof field !== "string")) {
            throw new AdminError("invalid_argument", "payload.fields values must be strings.");
          }
          await adapter.index({
            resource: target.resource,
            documents: [{ id: target.id, fields: fields as Record<string, string> }],
            signal: request.context.signal,
          });
          return accepted({ indexed: 1, resource: target.resource });
        }
        case "searchfn.documents.batch-index": {
          const payload = object(input.payload, "payload");
          const resource = string(payload.resource, "payload.resource");
          if (!resources.includes(resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          const entries = documents(payload.documents);
          await adapter.index({ resource, documents: entries, signal: request.context.signal });
          return accepted({ indexed: entries.length, resource });
        }
        case "searchfn.documents.remove-document": {
          const target = splitDocumentId(string(input.id, "id"));
          if (!resources.includes(target.resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          await adapter.remove({ resource: target.resource, ids: [target.id], signal: request.context.signal });
          return accepted({ removed: 1, resource: target.resource });
        }
        case "searchfn.indexes-collections.clear-index": {
          const resource = string(input.id, "id");
          if (!resources.includes(resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          await adapter.clear(resource, request.context.signal);
          return accepted({ cleared: resource });
        }
        default:
          throw new AdminError("not_found", `Unsupported SearchFn admin operation: ${request.operationId}.`);
      }
    },
  };
}
import { SendfnError } from "sendfn";
import { AdminError, type AdminOperationContext } from "@superfunctions/admin";
import type {
  SendFnAdminJson,
  SendFnAdminService,
  SendFnDomainAdminServiceOptions,
} from "./types.js";

function toAdminJson<T>(value: T): SendFnAdminJson<T> {
  const visit = (current: unknown): unknown => {
    if (current instanceof Date) return current.toISOString();
    if (Array.isArray(current)) return current.map(visit);
    if (!current || typeof current !== "object") return current;
    return Object.fromEntries(
      Object.entries(current as Record<string, unknown>)
        .filter(([, item]) => item !== undefined)
        .map(([key, item]) => [key, visit(item)]),
    );
  };
  return visit(value) as SendFnAdminJson<T>;
}

function safeDeviceToken<T extends { token: string }>(value: T): SendFnAdminJson<T> {
  return { ...toAdminJson(value), token: "[REDACTED]" } as SendFnAdminJson<T>;
}

function parseDate(value: string, label: string): Date {
  const parsed = new Date(value);
  if (!Number.isFinite(parsed.getTime())) {
    throw new AdminError("invalid_argument", `${label} must be a valid date-time.`);
  }
  return parsed;
}

function requiredIdempotencyKey(context: AdminOperationContext): string {
  if (!context.idempotencyKey) {
    throw new AdminError("precondition_failed", "This SendFn operation requires an idempotency key.");
  }
  return context.idempotencyKey;
}

function translateSendFnError(error: unknown): never {
  if (error instanceof AdminError) throw error;
  if (!(error instanceof SendfnError)) {
    throw new AdminError("internal", "SendFn could not complete the administration operation.", { cause: error });
  }

  if (error.code === "SENDFN_VALIDATION_ERROR" || error.code === "SENDFN_TEMPLATE_ERROR") {
    throw new AdminError("invalid_argument", error.message, {
      details: error.details,
      retryable: error.retryable,
      cause: error,
    });
  }
  if (error.code === "SENDFN_SUPPRESSION_ERROR") {
    throw new AdminError("conflict", error.message, {
      details: error.details,
      retryable: error.retryable,
      cause: error,
    });
  }
  if (error.code.endsWith("_PROVIDER_ERROR") || error.code === "SENDFN_DATABASE_ERROR") {
    throw new AdminError("dependency_unavailable", error.message, {
      details: error.details,
      retryable: error.retryable,
      cause: error,
    });
  }
  throw new AdminError("internal", "SendFn could not complete the administration operation.", {
    details: { domainCode: error.code },
    retryable: error.retryable,
    cause: error,
  });
}

async function domain<T>(operation: () => Promise<T>): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    return translateSendFnError(error);
  }
}

/**
 * Binds a project-owned public SendFn client to the shared administration
 * contract. No database or provider is accessed directly, so SendFn's
 * validation, suppression, provider, event, and storage invariants remain the
 * authoritative domain boundary.
 */
export function createSendFnDomainAdminService(
  options: SendFnDomainAdminServiceOptions,
): SendFnAdminService {
  if (!options.projectId.trim()) {
    throw new AdminError("invalid_argument", "SendFn admin binding requires a projectId.");
  }
  const { sendfn, projectId } = options;

  const assertProject = (context: AdminOperationContext): void => {
    if (!context.scope.projectId || context.scope.projectId !== projectId) {
      throw new AdminError("forbidden", "The active project cannot access this SendFn client.");
    }
  };

  return {
    async listTemplates(_input, context) {
      assertProject(context);
      const templates = await domain(() => sendfn.listTemplates());
      return { items: toAdminJson(templates), nextCursor: null };
    },

    async getTemplate(input, context) {
      assertProject(context);
      const template = await domain(() => sendfn.getTemplate(input.id));
      if (!template) {
        throw new AdminError("not_found", "The SendFn template was not found in the active project.");
      }
      return { item: toAdminJson(template) };
    },

    async registerTemplate(input, context) {
      assertProject(context);
      await domain(() => sendfn.registerTemplate(input.template));
      return { accepted: true };
    },

    async listDeliveries(input, context) {
      assertProject(context);
      const { startAt, endAt, ...query } = input;
      const events = await domain(() => sendfn.queryEvents({
        ...query,
        ...(startAt ? { startAt: parseDate(startAt, "startAt") } : {}),
        ...(endAt ? { endAt: parseDate(endAt, "endAt") } : {}),
      }));
      return { items: toAdminJson(events), nextCursor: null };
    },

    async sendEmail(input, context) {
      assertProject(context);
      const transaction = await domain(() => sendfn.email({
        ...input,
        idempotencyKey: requiredIdempotencyKey(context),
      }));
      return { item: toAdminJson(transaction) };
    },

    async sendBulkEmail(input, context) {
      assertProject(context);
      const rootKey = requiredIdempotencyKey(context);
      const transactions = await domain(() => sendfn.bulkEmail(
        input.messages.map((message, index) => ({
          ...message,
          idempotencyKey: `${rootKey}:${index}`,
        })),
      ));
      return { items: toAdminJson(transactions) };
    },

    async sendSms(input, context) {
      assertProject(context);
      return { item: toAdminJson(await domain(() => sendfn.sms(input))) };
    },

    async sendWhatsApp(input, context) {
      assertProject(context);
      return { item: toAdminJson(await domain(() => sendfn.whatsapp(input))) };
    },

    async sendPush(input, context) {
      assertProject(context);
      return { item: toAdminJson(await domain(() => sendfn.push(input))) };
    },

    async sendBulkPush(input, context) {
      assertProject(context);
      return { items: toAdminJson(await domain(() => sendfn.bulkPush(input.messages))) };
    },

    async listSuppressions(input, context) {
      assertProject(context);
      const items = await domain(() => sendfn.exportSuppressionList(input.limit, input.offset));
      return { items: toAdminJson(items), nextCursor: null };
    },

    async getSuppression(input, context) {
      assertProject(context);
      const result = await domain(() => sendfn.checkSuppressionList(input.email));
      return {
        suppressed: result.suppressed,
        item: result.entry ? toAdminJson(result.entry) : null,
      };
    },

    async addSuppression(input, context) {
      assertProject(context);
      const item = await domain(() => sendfn.addToSuppressionList({
        email: input.email,
        reason: input.reason,
        source: input.source,
        bounceType: input.bounceType ?? null,
        metadata: input.metadata ?? {},
        suppressedAt: input.suppressedAt
          ? parseDate(input.suppressedAt, "suppressedAt")
          : context.now ?? new Date(),
      }));
      return { accepted: true, item: toAdminJson(item), email: item.email };
    },

    async removeSuppression(input, context) {
      assertProject(context);
      await domain(() => sendfn.removeFromSuppressionList(input.email));
