      "plugfn.workflows.list", "plugfn.workflows.get", "plugfn.workflows.stats", "plugfn.workflows.enable", "plugfn.workflows.disable", "plugfn.workflows.delete",
      "plugfn.webhook-receipts.get", "plugfn.webhook-deliveries.list",
