  if (connection.ownerKind === 'user' && connection.ownerId === userId) {
    return true;
  }

  if (connection.ownerKind === 'organization' && connection.installedByUserId === userId) {
    return true;
  }

  if (connection.ownerKind === 'delegated' && connection.delegatedToUserId === userId) {
    return true;
  }

